 * M1 R1 — THE shared target-scoped business-registry rule (server: lib/businessRegistry.js classifyRegistryTarget,
 * used by the Core cost-history writer and the P1 supplier-credit routes), over the parsed app-businesses list. The
 * requested business is registered iff exactly ONE record's id is the string bizId and no other element's identity
 * collides with it (a non-string / null / missing id or a bare primitive whose String() is bizId, or a trimmed
 * variant). A defect confined to an unrelated record never makes the requested business unavailable.
 */
function registryTargetRegistered(list, bizId) {
  if (!Array.isArray(list) || typeof bizId !== "string" || !bizId || bizId.length > 128 || /[.#$\[\]\/:]/.test(bizId)) return false;
  var canonical = 0, collisions = 0;
  for (var i = 0; i < list.length; i++) {
    var e = list[i], rec = e !== null && typeof e === "object" && !Array.isArray(e);
    var id = rec ? e.id : (typeof e === "string" || typeof e === "number" || typeof e === "boolean") ? e : undefined;
    if (rec && typeof id === "string" && id === bizId) { canonical++; continue; }
    if ((rec || id !== undefined) && String(id).trim() === bizId.trim()) collisions++;
  }
  return canonical === 1 && collisions === 0;
}
